2zfjql2text11"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL陈志：慕玲姐，阿宝被人抓走了！NOR]],["id"]=[[rlt_22zfjql2text11]]},["rlt_22zfjql2text12"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN薛五义见你站在一旁无动于衷，便一把将张萱甩开，扯着阿宝离开了。NOR
YEL薛五义：哼，算你识相！NOR]],["id"]=[[rlt_22zfjql2text12]]},["rlt_22zfjql2text13"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL张萱：来人啊！抢小孩啦！NOR]],["id"]=[[rlt_22zfjql2text13]]},["rlt_22zfjql2text14"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL陈志：阿宝！慕玲姐，有人抓走了阿宝！NOR]],["id"]=[[rlt_22zfjql2text14]]},["rlt_22zfjql2text15"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL薛五义：你，你，你是小玲吧！小玲我是你爹啊！你快劝劝你妹妹，叫她别闹脾气了，快与我回家！NOR
YEL薛慕玲：爹？我可没爹！你十两银子把我卖了以后，我们已经没有关系了！NOR
薛五义：你，你怎么这般冷血！爹那时候也是迫不得已！我不想你跟着我受苦啊，我也是想给你找个好人家，叫你过得好点。你看你现在这不是过得挺好的么，若是没我，你能有今天？NOR
YEL薛慕玲：死不要脸，赶紧滚！再不滚别怪我不客气！NOR
YEL薛五义：你！你忘恩负义！你给我等着！NOR]],["id"]=[[rlt_22zfjql2text15]]},["rlt_22zfjql2text16"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN技巧槽【探水囚鱼-识】可解锁。NOR]],["id"]=[[rlt_22zfjql2text16]]},["rlt_22zfjql2text17"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL张萱：阿宝不怕，有我们在，绝对不让你被抓走。NOR]],["id"]=[[rlt_22zfjql2text17]]},["rlt_22zfjql2text18"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL陈志：阿宝，我会保护你的！NOR]],["id"]=[[rlt_22zfjql2text18]]},["rlt_22zfjql2text19"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN她受了惊吓，缩在薛慕玲身后，说不出话。NOR]],["id"]=[[rlt_22zfjql2text19]]},["rlt_22zfjql2text20"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL薛慕玲：多谢少侠出手，那人好赌成性，卖妻卖女，阿宝落他手里肯定讨不了好。NOR]],["id"]=[[rlt_22zfjql2text20]]},["rlt_22zfjql2text21"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL薛慕玲：他带着阿宝定走不远！现在追还来得及！NOR]],["id"]=[[rlt_22zfjql2text21]]},["rlt_22zfjql2text22"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL张萱：阿宝说了不走，少侠，你快拦住他。NOR]],["id"]=[[rlt_22zfjql2text22]]},["rlt_22zftx01addnpc01"]={["arg1"]=[[添加人物]],["arg2"]=[[22zftx01npc01]],["id"]=[[rlt_22zftx01addnpc01]]},["rlt_22zftx01addnpc02"]={["arg1"]=[[添加人物]],["arg2"]=[[22zftx01wp02]],["id"]=[[rlt_22zftx01addnpc02]]},["rlt_22zftx01addnpc03"]={["arg1"]=[[添加人物]],["arg2"]=[[22zftx01wp01]],["id"]=[[rlt_22zftx01addnpc03]]},["rlt_22zftx01ccbj01"]={["arg1"]=[[可传承玩家标记设置]],["arg2"]=[[zftx_01]],["arg3"]=1,["id"]=[[rlt_22zftx01ccbj01]]},["rlt_22zftx01change01"]={["arg1"]=[[换人]],["arg2"]=[[22zftx01npc01]],["arg3"]=[[22zftx01npc01a]],["id"]=[[rlt_22zftx01change01]]},["rlt_22zftx01change02"]={["arg1"]=[[换人]],["arg2"]=[[22zftx01wp01]],["arg3"]=[[22zftx01wp01a]],["id"]=[[rlt_22zftx01change02]]},["rlt_22zftx01change03"]={["arg1"]=[[换人]],["arg2"]=[[22zftx01npc01a]],["arg3"]=[[22zftx01npc01b]],["id"]=[[rlt_22zftx01change03]]},["rlt_22zftx01change04"]={["arg1"]=[[换人]],["arg2"]=[[22zftx01wp01a]],["arg3"]=[[22zftx01wp01]],["id"]=[[rlt_22zftx01change04]]},["rlt_22zftx01change05"]={["arg1"]=[[换人]],["arg2"]=[[22zftx01npc01b]],["arg3"]=[[22zftx01npc01c]],["id"]=[[rlt_22zftx01change05]]},["rlt_22zftx01delenpc01"]={["arg1"]=[[删除人物]],["arg2"]=[[22zftx01wp02]],["id"]=[[rlt_22zftx01delenpc01]]},["rlt_22zftx01delenpc02"]={["arg1"]=[[删除人物]],["arg2"]=[[22zftx01npc01c]],["id"]=[[rlt_22zftx01delenpc02]]},["rlt_22zftx01dtbj01"]={["arg1"]=[[地图标记设置]],["arg2"]=[[zftx01_rwjd]],["arg3"]=1,["id"]=[[rlt_22zftx01dtbj01]]},["rlt_22zftx01dtbj02"]={["arg1"]=[[地图标记设置]],["arg2"]=[[zftx01_rwjd]],["arg3"]=2,["id"]=[[rlt_22zftx01dtbj02]]},["rlt_22zftx01item01"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[22zftx01item01]],["arg3"]=1,["id"]=[[rlt_22zftx01item01]]},["rlt_22zftx01item01c"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[22zftx01item01]],["arg3"]=-1,["id"]=[[rlt_22zftx01item01c]]},["rlt_22zftx01jgj01"]={["arg1"]=[[结果集]],["arg2"]=[[22zftx01text08]],["id"]=[[rlt_22zftx01jgj01]]},["rlt_22zftx01jgj02"]={["arg1"]=[[结果集]],["arg2"]=[[22zftx01text09;22zftx01item01;22zftx01delenpc01]],["id"]=[[rlt_22zftx01jgj02]]},["rlt_22zftx01js"]={["arg1"]=[[更新拳脚系统标记]],["arg2"]=[[2004txkq]],["arg4"]=[[22zftx01ccbj01;22zftx01text13;22zftx01text14;22zftx01tctext01;22zftx01delenpc02]],["id"]=[[rlt_22zftx01js]]},["rlt_22zftx01sjjg01"]={["arg1"]=[[随机结果]],["arg2"]=[[22zftx01jgj01;22zftx01jgj02]],["arg3"]=[[3;7]],["id"]=[[rlt_22zftx01sjjg01]]},["rlt_22zftx01tctext01"]={["arg1"]=[[弹出文本]],["arg2"]=[[特性【游鱼】、【困水】已解锁。]],["id"]=[[rlt_22zftx01tctext01]]},["rlt_22zftx01text01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL苗霏：救……救命……NOR]],["id"]=[[rlt_22zftx01text01]]},["rlt_22zftx01text02"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL苗霏：救命啊……NOR]],["id"]=[[rlt_22zftx01text02]]},["rlt_22zftx01text03"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN你几步走到苗霏身旁，将她自水中扶起，这才发现水面才及她胸口，但苗霏吓得不轻，你先扶着她回到岸上。NOR]],["id"]=[[rlt_22zftx01text03]]},["rlt_22zftx01text04"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL苗霏：谢谢少侠，我还以为我今日就要含恨九泉了。NOR
YEL苗霏：啊！我，我的玉坠不见了……NOR
